begin;
do $$
declare au uuid:=gen_random_uuid(); mu uuid:=gen_random_uuid(); ou uuid:=gen_random_uuid();
 cid uuid; m uuid; other uuid; archived uuid; p uuid; p2 uuid; p3 uuid; rejected boolean; rid uuid; n integer;
begin
 insert into auth.users(id,email,email_confirmed_at) values(au,'reset-admin@example.invalid',now()),(mu,'reset-member@example.invalid',now()),(ou,'reset-other@example.invalid',now());
 insert into public.portal_admins(user_id) values(au);
 insert into public.cohorts(name,class_number,status) values('__reset_test',900009,'active') returning id into cid;
 insert into public.members(first_name,last_name,uf_email,cohort_id,auth_user_id,program_status) values('Reset','Member','reset-member@example.invalid',cid,mu,'active') returning id into m;
 insert into public.members(first_name,last_name,uf_email,cohort_id,auth_user_id,program_status) values('Reset','Other','reset-other@example.invalid',cid,ou,'active') returning id into other;
 insert into public.members(first_name,last_name,uf_email,cohort_id,program_status) values('Reset','Archived','reset-archived@example.invalid',cid,'archived') returning id into archived;
 insert into public.point_submissions(member_id,activity_name,activity_date,points_requested,points_awarded,status) values(m,'History',current_date,5,5,'approved') returning id into p;
 insert into public.point_submissions(member_id,activity_name,activity_date,points_requested,points_awarded,status) values(other,'History',current_date,5,5,'approved') returning id into p2;
 insert into public.point_submissions(member_id,activity_name,activity_date,points_requested,points_awarded,status) values(archived,'History',current_date,5,5,'approved') returning id into p3;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',mu,'role','authenticated')::text,true);
 perform set_config('role','authenticated',true);
 rejected:=false; begin perform public.portal_reset_points(null,'RESET'); exception when others then rejected:=true; end;
 if not rejected then raise exception 'Member could reset points'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',au,'role','authenticated')::text,true);
 rejected:=false; begin perform public.portal_reset_points(m,'wrong'); exception when others then rejected:=true; end;
 if not rejected then raise exception 'Missing confirmation accepted'; end if;
 n:=public.portal_reset_points(m,'RESET');
 if n<>1 or (select points_awarded from public.point_submissions where id=p)<>0 or (select points_awarded from public.point_submissions where id=p2)<>5 then raise exception 'Single reset scope'; end if;
 if not exists(select 1 from public.activity_log where entity_id=p and action='update') then raise exception 'Reset audit missing'; end if;
 perform public.portal_reset_points(null,'RESET');
 if (select points_awarded from public.point_submissions where id=p2)<>0 or (select points_awarded from public.point_submissions where id=p3)<>5 then raise exception 'All active reset scope'; end if;
 perform set_config('role','none',true);
 update public.cohorts set status='archived' where id=cid;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',mu,'role','authenticated')::text,true);
 perform set_config('role','authenticated',true);
 insert into storage.objects(bucket_id,name,metadata) values('trailblazers-private',mu||'/resume.pdf','{"mimetype":"application/pdf"}');
 rid:=public.portal_submit_file('resume',mu||'/resume.pdf','resume.pdf');
 if rid is null then raise exception 'Resume submission failed'; end if;
 rejected:=false; begin insert into storage.objects(bucket_id,name,metadata) values('trailblazers-private',ou||'/forbidden.pdf','{"mimetype":"application/pdf"}'); exception when others then rejected:=true; end;
 if not rejected then raise exception 'Cross-account upload allowed'; end if;
 rejected:=false; begin insert into storage.objects(bucket_id,name,metadata) values('trailblazers-private',mu||'/points.png','{"mimetype":"image/png"}'); exception when others then rejected:=true; end;
 if not rejected then raise exception 'Archived cohort points allowed'; end if;
end $$;
rollback;
